package pro.livemic.studio;

import android.content.*;
import android.os.*;
import android.util.AtomicFile;
import org.json.*;
import java.io.*;
import java.util.UUID;
import java.util.concurrent.*;

/** Application-owned vocal loop session. Disk and native file operations run on one worker. */
final class HarmonySession {
    private static HarmonySession instance;
    static synchronized HarmonySession get(Context c){if(instance==null)instance=new HarmonySession(c.getApplicationContext());return instance;}
    final Context context;final File dir;final ExecutorService worker=Executors.newSingleThreadExecutor();final Handler main=new Handler(Looper.getMainLooper());
    int bpm=90,meter=0,bars=4,key=0,scale=0,preset=0,revision=0;boolean auto=false,liveOn=false;float wet=.45f,dry=1,spread=.65f;
    final float[] volume={1,1,1,1},pan={0,0,0,0};final boolean[] muted=new boolean[4];final String[] files=new String[4],previous=new String[4];
    volatile boolean ready=false,busy=true;String error="",message="";double[] state={0,0,0,0,-1,-1,0,0,-1,-1,-1,0,0,-1};long completed=0;int nativeError=0;boolean metadataDirty=false;
    private HarmonySession(Context c){context=c;dir=new File(c.getFilesDir(),"vocal-harmony");worker.execute(this::restore);}
    private File safe(String name)throws IOException{if(name==null||!name.matches("[a-zA-Z0-9_-]+\\.wav"))throw new IOException("잘못된 성부 파일 이름");return new File(dir,name);}
    private void restore(){try{if(!dir.exists()&&!dir.mkdirs())throw new IOException("저장 폴더를 만들 수 없습니다");File meta=new File(dir,"session.json");if(meta.exists()||new File(dir,"session.json.bak").exists()){byte[] bytes=new AtomicFile(meta).readFully();JSONObject j=new JSONObject(new String(bytes,java.nio.charset.StandardCharsets.UTF_8));if(j.optInt("version")!=1)throw new IOException("지원하지 않는 저장 형식");bpm=j.optInt("bpm",90);meter=j.optInt("meter",0);bars=j.optInt("bars",4);key=j.optInt("key",0);scale=j.optInt("scale",0);preset=j.optInt("preset",0);auto=j.optBoolean("auto",false);wet=(float)j.optDouble("wet",.45);dry=(float)j.optDouble("dry",1);spread=(float)j.optDouble("spread",.65);JSONArray layers=j.optJSONArray("layers");if(layers!=null)for(int i=0;i<Math.min(4,layers.length());i++){JSONObject l=layers.getJSONObject(i);files[i]=l.optString("file",null);previous[i]=l.optString("previous",null);volume[i]=(float)l.optDouble("volume",1);pan[i]=(float)l.optDouble("pan",0);muted[i]=l.optBoolean("muted",false);if(files[i]!=null)safe(files[i]);if(previous[i]!=null)safe(previous[i]);}}
        if(bpm<40||bpm>240||meter<0||meter>2||(bars!=4&&bars!=8)||key<0||key>=MusicTheory.ROOTS.length||scale<0||scale>=MusicTheory.SCALES.length||preset<0||preset>3||!Float.isFinite(wet)||wet<0||wet>1||!Float.isFinite(dry)||dry<0||dry>1||!Float.isFinite(spread)||spread<0||spread>1)throw new IOException("저장 설정 범위 오류");for(int i=0;i<4;i++)if(!Float.isFinite(volume[i])||volume[i]<0||volume[i]>1||!Float.isFinite(pan[i])||pan[i]<-1||pan[i]>1)throw new IOException("성부 설정 범위 오류");
        if(!NativeHarmony.prepare(bpm,meter,bars))throw new IOException("루프 준비 실패");for(int i=0;i<4;i++){if(files[i]!=null&&!NativeHarmony.loadLayer(i,safe(files[i]).getAbsolutePath()))throw new IOException((i+1)+"성부 불러오기 실패");NativeHarmony.layer(i,volume[i],pan[i],muted[i]);}cleanup(json());main.post(()->{ready=true;busy=false;configure();revision++;});
    }catch(Exception e){main.post(()->{busy=false;error="보컬 화음 준비 실패: "+e.getMessage();revision++;});}}
    JSONObject json()throws JSONException{JSONObject j=new JSONObject().put("version",1).put("bpm",bpm).put("meter",meter).put("bars",bars).put("key",key).put("scale",scale).put("preset",preset).put("auto",auto).put("wet",wet).put("dry",dry).put("spread",spread);JSONArray layers=new JSONArray();for(int i=0;i<4;i++)layers.put(new JSONObject().put("file",files[i]).put("previous",previous[i]).put("volume",volume[i]).put("pan",pan[i]).put("muted",muted[i]));return j.put("layers",layers);}
    void write(JSONObject j)throws Exception{AtomicFile f=new AtomicFile(new File(dir,"session.json"));FileOutputStream out=f.startWrite();try{out.write(j.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));f.finishWrite(out);}catch(Exception e){f.failWrite(out);throw e;}cleanup(j);}
    void cleanup(JSONObject metadata){try{java.util.Set<String> referenced=new java.util.HashSet<>();JSONArray layers=metadata.getJSONArray("layers");for(int i=0;i<layers.length();i++){JSONObject layer=layers.getJSONObject(i);for(String key:new String[]{"file","previous"}){String name=layer.optString(key,null);if(name!=null)referenced.add(name);}}File[] entries=dir.listFiles();if(entries!=null)for(File entry:entries){String name=entry.getName();if(name.matches("[a-zA-Z0-9_-]+\\.wav")&&!referenced.contains(name)&&entry.isFile())entry.delete();}}catch(Exception e){android.util.Log.w("VocalHarmony","성부 파일 정리를 건너뜁니다",e);}}
    void persist(){if(busy){metadataDirty=true;return;}try{JSONObject snapshot=json();worker.execute(()->{try{write(snapshot);}catch(Exception e){main.post(()->{error="설정 저장 실패: "+e.getMessage();revision++;});}});}catch(Exception e){error=e.getMessage();}}
    void configure(){if(ready)NativeHarmony.configure(liveOn&&auto,key,scale,preset,wet,dry,spread);}
    void changed(){configure();persist();revision++;}
    void live(boolean on){if(on){ComposerSession.get(context).voice(false);}else NativeHarmony.cancel();liveOn=on;configure();if(on)NativeHarmony.monitor(AudioService.canMonitor(context));revision++;}
    void monitor(boolean on){NativeHarmony.monitor(on);}
    boolean locked(){if(!ready||busy){error="저장 또는 준비가 끝날 때까지 기다려 주세요.";return true;}if(state[4]>=0||state[5]>=0){error="성부 녹음을 마친 뒤 변경하세요.";return true;}return false;}
    void loopSettings(int b,int m,int n){if(locked())return;for(String f:files)if(f!=null){error="성부를 비운 뒤 변경하세요.";return;}stop();busy=true;revision++;worker.execute(()->{boolean ok=NativeHarmony.prepare(b,m,n);main.post(()->{busy=false;if(ok){bpm=b;meter=m;bars=n;for(int i=0;i<4;i++)previous[i]=null;configure();persist();}else error="루프 준비 실패";flushMetadata();revision++;});});}
    void play(){if(!ready||busy){error="루프를 준비하고 있습니다.";return;}AudioService.harmonyRequested=true;context.startForegroundService(new Intent(context,AudioService.class).setAction(AudioService.PLAYBACK));NativeHarmony.transport(1);revision++;}
    void pause(){NativeHarmony.transport(2);revision++;}
    void stopNative(){NativeHarmony.cancel();NativeHarmony.transport(0);AudioService.harmonyRequested=false;revision++;}
    void stop(){stopNative();if(AudioService.playbackActive)context.startService(new Intent(context,AudioService.class).setAction(AudioService.HARMONY_STOP));}
    void arm(int slot){if(locked())return;if(!liveOn||!AudioService.active){error="마이크를 먼저 켜세요.";return;}AudioService.harmonyRequested=true;context.startForegroundService(new Intent(context,AudioService.class).setAction(AudioService.PLAYBACK));if(!NativeHarmony.arm(slot)){AudioService.harmonyRequested=false;error="성부 녹음을 시작하지 못했습니다.";return;}state=NativeHarmony.state();revision++;}
    void cancel(){NativeHarmony.cancel();state=NativeHarmony.state();revision++;message="녹음을 취소했습니다. 이전 성부는 유지됩니다.";}
    void levels(int slot){NativeHarmony.layer(slot,volume[slot],pan[slot],muted[slot]);persist();revision++;}
    void releaseIfStopped(){if(AudioService.playbackActive)context.startService(new Intent(context,AudioService.class).setAction(AudioService.HARMONY_STOP));}
    void flushMetadata(){if(metadataDirty){metadataDirty=false;persist();}}
    JSONObject transaction(int slot,String file,String prior)throws JSONException{JSONObject snapshot=json();snapshot.getJSONArray("layers").getJSONObject(slot).put("file",file==null?JSONObject.NULL:file).put("previous",prior==null?JSONObject.NULL:prior);return snapshot;}
    void clear(int slot){if(locked())return;String old=files[slot];if(old==null)return;try{JSONObject snapshot=transaction(slot,null,old);busy=true;revision++;worker.execute(()->{try{write(snapshot);main.post(()->{NativeHarmony.clear(slot);previous[slot]=old;files[slot]=null;busy=false;flushMetadata();revision++;});}catch(Exception e){main.post(()->{busy=false;flushMetadata();error="성부 삭제 실패: "+e.getMessage();revision++;});}});}catch(Exception e){error=e.getMessage();}}
    /** transport(0) sets playing synchronously unless native is in an exclusive operation. */
    boolean stopForLoad(){for(int attempt=0;attempt<100;attempt++){NativeHarmony.transport(0);double[] now=NativeHarmony.state();if(now[0]==0&&now[4]<0&&now[5]<0)return true;Thread.yield();}return false;}
    void undo(int slot){if(locked()||previous[slot]==null)return;AudioService.harmonyRequested=false;String target=previous[slot],old=files[slot];try{JSONObject snapshot=transaction(slot,target,old);busy=true;revision++;worker.execute(()->{try{if(!stopForLoad()||!NativeHarmony.loadLayer(slot,safe(target).getAbsolutePath()))throw new IOException("이전 성부를 열 수 없습니다");write(snapshot);main.post(()->{files[slot]=target;previous[slot]=old;busy=false;flushMetadata();releaseIfStopped();revision++;});}catch(Exception e){if(old!=null)try{if(stopForLoad())NativeHarmony.loadLayer(slot,safe(old).getAbsolutePath());}catch(Exception ignored){}else NativeHarmony.clear(slot);main.post(()->{busy=false;flushMetadata();releaseIfStopped();error="되돌리기 실패: "+e.getMessage();revision++;});}});}catch(Exception e){error=e.getMessage();}}
    void poll(){if(!ready)return;double[] prior=state;state=NativeHarmony.state();if(prior[0]!=state[0]||prior[4]!=state[4]||prior[5]!=state[5])revision++;int code=(int)state[12];if(code!=nativeError){nativeError=code;if(code>0){error="보컬 루프 오류 ("+code+") · 저장된 성부를 확인하세요.";revision++;}}long rev=(long)state[6];if(rev!=completed){completed=rev;int slot=(int)state[13];if(slot>=0&&slot<4)saveCompleted(slot);} }
    void saveCompleted(int slot){String old=files[slot],name=UUID.randomUUID().toString()+".wav";try{JSONObject snapshot=transaction(slot,name,old);busy=true;revision++;worker.execute(()->{try{File file=safe(name);if(!NativeHarmony.saveLayer(slot,file.getAbsolutePath()))throw new IOException("오디오 파일 저장 실패");write(snapshot);main.post(()->{files[slot]=name;previous[slot]=old;busy=false;flushMetadata();message=(slot+1)+"성부를 저장했습니다.";revision++;});}catch(Exception e){if(old!=null)try{if(!stopForLoad()||!NativeHarmony.loadLayer(slot,safe(old).getAbsolutePath()))throw new IOException("이전 성부 복원 실패");}catch(Exception restore){e.addSuppressed(restore);}else NativeHarmony.clear(slot);main.post(()->{busy=false;flushMetadata();if(old!=null){AudioService.harmonyRequested=false;releaseIfStopped();}error="성부 저장 실패: "+e.getMessage()+(e.getSuppressed().length>0?" · 이전 성부를 다시 불러오지 못했습니다.":"");revision++;});}});}catch(Exception e){error=e.getMessage();}}
}
